fn find_max(v: Vec<Int>) -> Option<Int> {
    if len(v) == 0 {
        None
    } else {
        let mut max_value = get(v, 0)?
        for x in v {
            if x > max_value {
                max_value = x
            }
        }
        Some(max_value)
    }
}

